insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 1, 'A designer changes the diameter of a fixed-roof tank and re-runs the shell calculation on its own. What does the opening lesson of this tier have against that?', '["Nothing, provided the design liquid level was held, because the venting here is keyed to that level rather than to the capacity.", "The capacity, the venting and the fire case are all read off the same geometry, so the venting has been moved without being looked at.", "Nothing, because the engine returns the venting totals in the same result whenever a shell geometry is submitted to it.", "The shell is the only answer a diameter moves, because the fire case is taken from the effective wetted height."]'::jsonb, 1, 'The nominal capacity of 19608.4845 bbl is what the thermal rate is carried per barrel of, and the shell a fire wets is the same shell, so one geometry change moves three answers.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 2, 'The engine returns a nominal capacity of 110093.4703 ft3 and 19608.4845 bbl for this tank. How does a reader confirm the second from the first without trusting the engine?', '["Divide the returned cubic feet by the barrels per foot of shell of 544.6801, which is the figure the result carries for turning a height into an inventory in barrels.", "Multiply the returned cubic feet by the cross section of 3058.1520 ft2, since the cross section is what carries a volume in feet across into a volume in barrels.", "There is no way to confirm it, because the conversion used is module private.", "Divide the returned cubic feet by the returned cubic feet in a barrel, which the result hands back as 5.614583333333333."]'::jsonb, 3, 'The conversion is exact by definition and tankCapacity returns it as ft3PerBbl, so the barrels can be audited in one division rather than assumed.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 3, 'Why does the tank result hand back the cubic feet in a barrel at all, when every engineer using it already knows the conversion?', '["A conversion a package holds privately is one a reader is trusting on somebody else''s word, and a returned one can be audited in a second.", "Because the conversion in force changes with the temperature base the volumes are reported at.", "Because the conversion is a stated input the caller supplies, as the minimum plate thickness is.", "Because the API MPMS correction tables are not carried, so the factor has to travel with the barrel."]'::jsonb, 0, 'It is exact by definition and returned as ft3PerBbl, which is why a reader can divide 110093.4703 ft3 by it and see whether the barrels agree.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 4, 'A venting question and a custody transfer question are asked about the same tank. Which capacity does each one take?', '["Both take the working capacity of 18845.9323 bbl, because nobody fills a fixed-roof tank to the top of the shell and a vent sized on a volume the tank never holds is oversized.", "Venting takes the working capacity of 18845.9323 bbl and the inventory question the nominal of 19608.4845 bbl.", "Venting takes the nominal capacity of 19608.4845 bbl, and the inventory question takes the working capacity of 18845.9323 bbl.", "Both take the nominal capacity of 19608.4845 bbl, since the design liquid level is an operating limit."]'::jsonb, 2, 'The thermal rate in this package is carried per barrel of capacity, and the inbreathing the engine returns for this tank is 19608.4845 scfh, which is the nominal capacity keyed straight through.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 5, 'What makes the choice between the two capacities such a quiet mistake to make?', '["Both are volumes in barrels for the right tank, so a result built on the wrong one still looks like a tank.", "The engine returns only one of them on any given call, so a reader who needs the other has to call again with a different flag and may forget which one the first call gave.", "The two are close enough that no downstream check can separate them, since every tolerance in this course is set at half a unit in the last place of the class printed.", "The working capacity is returned in barrels and the nominal in cubic feet, so a mix-up shows up as a units error rather than as a wrong volume."]'::jsonb, 0, 'The engine returns 19608.4845 bbl and 18845.9323 bbl side by side and both are honest answers to different questions, which is why the result carries a name against each.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 6, 'The digest prints a relation between the two capacities of this tank. What does it actually give a writer permission to say?', '["That the working capacity is the larger of the two by 762.5522 bbl, which is the difference printed as the first value less the second.", "That the ratio of 1.040462 is the working capacity over the nominal, so the working figure is what the line divides by.", "That the gap is small enough to ignore in a screening calculation, which is the judgement the line supports.", "That the difference is 762.5522 bbl and the ratio is 1.040462, because the relation line carries both values, their difference and their ratio."]'::jsonb, 3, 'The relation names the nominal at 19608.4845 bbl first and the working at 18845.9323 bbl second, so the difference of 762.5522 and the ratio of 1.040462 both run in that order.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 7, 'Where does the gap between the nominal and the working capacity of this tank come from?', '["The working capacity is taken over a smaller cross section than the nominal one, because the engine works the design case off the inside of the shell plate and the nominal case off the full circle.", "The shell stands 36.000000 ft and the design liquid level is 34.600000 ft, so the working volume stops below the top of the shell.", "The nominal capacity is taken to the top of the roof and the working capacity to the top of the shell.", "The working capacity is reduced by the volume of the plate the shell is built from."]'::jsonb, 1, 'Both capacities are the same cross section of 3058.1520 ft2 taken over different heights, and the design liquid level of 34.600000 ft is what stops the working figure.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 8, 'Barrels per foot of shell comes back as 544.6801 on this tank. What is an operator actually doing with it?', '["Converting the nominal capacity into the working one, since multiplying it by the difference between the two heights is how a design liquid level is applied to a volume.", "Checking the shell course table, because a course of shell one foot high holds that many barrels and the course heights are what the shell calculation is banded on.", "Turning a gauge reading, which is a height, into an inventory, which is a volume.", "Reading off how much the tank can take in an hour, since a filling rate in barrels an hour becomes a rate of level rise once the figure is known."]'::jsonb, 2, 'On a vertical cylinder the cross section of 3058.1520 ft2 does not change with height, so the figure is constant and one multiplication turns a level into barrels.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 9, 'The design liquid level on this tank is moved and the diameter and the shell height are left alone. Which returned figure in the capacity block moves with it?', '["The working capacity, which is the volume to the design liquid level and is returned as 18845.9323 bbl at the stated level.", "The barrels per foot of shell, currently 544.6801, because the figure is the working capacity spread over the height the tank is actually filled to.", "The nominal capacity, currently 19608.4845 bbl, because a design level is the level a nominal volume is taken to.", "The cross section, currently 3058.1520 ft2, because the area the engine uses is the area available below the design liquid level rather than the full circle."]'::jsonb, 0, 'The nominal capacity is taken to the top of the shell at 36.000000 ft and the cross section comes from the diameter, so neither of them knows anything about the design level.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 10, 'Ask the tank capacity function for a fill height below zero. What comes back?', '["A capacity of zero barrels with a flag saying the fill height was clamped, which is the pattern the engine uses wherever an input falls outside a range it can still work in.", "The message `a fill height cannot be negative: a tank does not hold less than nothing`.", "A negative capacity in barrels, because the cross section and the conversion carry any height straight through, and a note advising that the sign be checked before use.", "An empty capacity field with no reason beside it, in the shape the fire venting result uses for a quantity the package will not compute."]'::jsonb, 1, 'The guard sits at the input rather than in the screen that calls it, so the caller gets a reason and never a number that would sum and average downstream.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 11, 'Why does a relation as simple as a cross section times a height need a guard at all?', '["Because the cross section of 3058.1520 ft2 is itself derived from a squared diameter, so a sign error in the geometry survives into the area and cannot be seen in it.", "Because the conversion of 5.614583333333333 cubic feet in a barrel would otherwise be applied twice to a height below zero, which is where the sign is actually lost.", "Because a fill height below zero is the only tank input the engine cannot detect.", "Multiplication has no opinion about physics, so a negative height returns a negative volume without complaint."]'::jsonb, 3, 'A negative inventory sums, averages and plots like any other number, and it can cancel a real volume somewhere else in a total, which is why the refusal belongs in the engine.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 12, 'A zero, a blank and a reason all appear in the same field on a screen. What is the lesson''s point about the three?', '["They are three renderings of one behaviour, so a caller can configure which of them the package returns.", "A blank and a reason mean the same thing to a downstream report, because neither of them carries a number.", "A zero says the tank holds nothing, a blank says the tool broke, and a reason says the question was malformed and names the part that was.", "A zero is the safest of the three in a datasheet, because a reader who sees it goes back to the source."]'::jsonb, 2, 'The tank capacity refusal returns the reason, and its message names the impossible input rather than leaving the caller with a value that looks like an answer.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 13, 'Why is the design of this tier built on three answers coming out of one short list of geometry?', '["Because a diameter, a shell height and a design liquid level are what the shell, the venting and the losses are all read from.", "Because the three tank functions are one call in the engine, so a caller who asks for a capacity is handed the venting totals and the loss figures in the same result.", "Because the standard behind each of the three answers is the same document.", "Because the three answers share a governing predicate the engine forms once."]'::jsonb, 0, 'From a diameter of 62.400000 ft and a shell height of 36.000000 ft the engine returns a cross section of 3058.1520 ft2 and a capacity of 19608.4845 bbl, and every later answer in the tier stands on those.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 14, 'This course prints volumes in barrels to four decimals. What happens to a reader who rounds 18845.9323 bbl further before quoting it?', '["Nothing at all, because a volume in the thousands carries no information in its later places and the tolerances in this course are set on relative terms instead.", "They can fall outside the tolerance, because every tolerance here is at least half a unit in the last place the course prints.", "They land inside the tolerance anyway, since a rounding is smaller than half a unit in the last place.", "The figure stops being quotable, because the course grades a rendering rather than a value."]'::jsonb, 1, 'Quote at the precision the source prints. A reader who reads the right row and copies it as printed is inside every tolerance this course sets.'),
  ('metering', 'advanced', 'module', 'm01-the-tank-and-its-geometry', 15, 'Which figure in the capacity block is the one this tier keeps calling back to when it talks about breathing?', '["The barrels per foot of shell at 544.6801, because the breathing terms are driven by how fast the level moves and that figure turns a level rate into a volume rate.", "The cross section of 3058.1520 ft2, because the vapour space above the liquid is the volume that breathes and the area is what sets it on a vertical cylinder.", "The nominal capacity of 19608.4845 bbl, because the thermal rate in this package is carried per barrel of capacity.", "The working capacity of 18845.9323 bbl, because that is the volume the tank is designed to hold."]'::jsonb, 2, 'Barrels per foot belongs to a gauge and the cross section to an area, and neither of them is what a rate per barrel of capacity is applied to.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 1, 'On the bottom course of this tank the engine returns 0.214385 in at the design condition, 0.218926 in at the test condition and a required thickness of 0.218926 in. What has decided the answer?', '["The hydrostatic test, because the required thickness is the largest of the two computed conditions and the stated minimum plate.", "The product, because a specific gravity of 0.912400 is the input the course was run at.", "The stated minimum plate thickness of 0.187500 in, which is the floor the engine applies.", "An average of the two conditions, which is what the one-foot method forms."]'::jsonb, 0, 'The engine returns hydrostatic test as the governing word on that row, and 0.218926 in is the test thickness rather than the design thickness of 0.214385 in.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 2, 'Across the gravity sweep on the bottom course the test thickness sits at 0.218926 in on every row. Why does that column never move?', '["Because the test thickness is clamped at the stated minimum plate thickness of 0.187500 in, so it cannot fall below it or rise above it while the product moves.", "Because the engine runs the test condition once and reuses it for every course, which is why one figure is carried down the whole of that column.", "The test is always water, and water does not care what the tank will eventually hold.", "Because the sweep holds the head constant at 34.600000 ft, and holding the head fixed fixes both of the computed thicknesses on the row."]'::jsonb, 2, 'The design column climbs from 0.129233 in at a gravity of 0.550000 to 0.270214 in at 1.150000 while the test column stays at 0.218926 in throughout.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 3, 'The digest reports that the water test takes the bottom course of this tank below a gravity of 0.931727. How was that figure obtained?', '["By reading it from the API 650 band table the package carries for the diameter of this tank.", "By bisecting the governing word the engine returns, narrowing the interval until the word changed.", "By interpolating linearly between the design thickness at a gravity of 0.912400 and the design thickness at 1.000000, which is the pair of rows the crossover falls between on the sweep.", "By rearranging the one-foot relation for the gravity at which the two computed thicknesses are equal, which is an exact solution rather than a search."]'::jsonb, 1, 'Nothing in the package publishes 0.931727 as a threshold, because it is a property of this geometry and this test condition rather than a published quantity.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 4, 'Which two rows of the gravity sweep bracket the reported crossover of 0.931727?', '["The row at 0.850000 and the row at 0.912400, which are the last two rows before the required thickness stops tracking the test column.", "The row at 1.000000 and the row at 1.150000, which are the two rows on which the design thickness stands above the test thickness of 0.218926 in.", "The row at 0.750000 and the row at 0.850000, where the design thickness passes 0.187500 in and the stated minimum stops being the largest of the three.", "The row at 0.912400, governed by the hydrostatic test, and the row at 1.000000, governed by product design."]'::jsonb, 3, 'The governing word is hydrostatic test at 0.912400 and product design at 1.000000, so the change lies between them and 0.931727 is inside that interval.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 5, 'Where does the minimum shell plate thickness of 0.187500 in on this tank come from?', '["It is read from the API 650 band table for this tank diameter, which the engine carries so that a minimum never has to be supplied by a caller at all.", "It is the thinnest plate the one-foot method can return at the head of the top course, so the engine takes it as a floor for every course below that one.", "It is a value the caller stated, which the engine applies and names in the result.", "It is a default the engine falls back on when no minimum is supplied, chosen so that a shell is never specified thinner than a plate a fabricator will roll."]'::jsonb, 2, 'The engine says so: API 650 bands the minimum by tank diameter and this package does not carry that band table, so the value in force is the caller''s.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 6, 'Four of the five courses on this tank come back at 0.187500 in. What is the engine telling a reader who sees that?', '["That neither computed condition asks for that much plate on those courses, so the stated floor is the largest of the three candidates.", "That the head on those four courses is too small for the one-foot relation to be applied, so the engine substitutes the floor.", "That the four courses were not evaluated at the test condition, since a test condition below the floor is not computed.", "That the stated minimum has been used as a starting value and refined upward on each of the four."]'::jsonb, 0, 'On course 5 the computed thicknesses are 0.010209 in and 0.010425 in, and the required thickness is still 0.187500 in because the floor governs.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 7, 'The engine returns five courses for this tank. What rule produced that count?', '["One course per whole course height that fits inside the shell height, with any remainder added to the topmost full course.", "One course per whole or part course height in the shell height, taken as the ceiling of the shell height divided by the course height.", "One course for every eight feet of design liquid level, which is why the count follows the level rather than the shell.", "One course per row the engine can evaluate at both conditions, so a course whose thickness falls below the floor is not counted."]'::jsonb, 1, 'The fifth course runs from 32.000000 ft to 36.000000 ft and is shorter than the four below it, and it counts because the rule takes a part course as a course.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 8, 'Why can a reader be sure the bottom course of a shell computed this way is the thickest?', '["Because the engine sorts the courses by required thickness before it returns them, which puts the thickest at the bottom of the table.", "Because the bottom course is the only one evaluated at the hydrostatic test condition, and a test condition always asks for more plate.", "Because the bottom course is the tallest, and the one-foot method scales the thickness with the height of the course it is applied to.", "The head falls as the courses go up, both thickness relations are linear in it, and the stated minimum is a floor, so the required thickness cannot increase upward."]'::jsonb, 3, 'The engine returns that as a property of its method and sets its own flag to true for it, which is a claim a reader can check against the table rather than a single result.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 9, 'On this tank one course is governed by the hydrostatic test and four by the stated minimum plate thickness. What does the pair of counts rest on?', '["One courses array, with the governing word the engine returns deciding which count a course falls into.", "Two separate sweeps, one run at the test condition and one run against the floor.", "The required thickness column, with any course standing above 0.187500 in counted as a test case and every other course counted against the floor.", "The head column, with the courses whose head is taken below the design liquid level counted separately from the courses above it."]'::jsonb, 0, 'Both counts are taken over the same courses array, and the rule is that a course counts when the engine returns that governing word, which is what tells the two apart.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 10, 'The engine writes a note wherever the water test decides a course. Which sentence is it?', '["A note saying that the product design thickness has been superseded by a test value and that the test value is the one to procure plate against, with the design figure retained beside it for reference on any later change of service.", "A note saying that the hydrostatic test head is taken from the design liquid level and that a tank tested to a different level has to be re-run before the thickness is used.", "`the water test governs this course: a light product does not stress the shell as hard as the water it will be tested with, and designing for the product alone would under-thickness it`", "A note saying that the water test is the governing case on every tank below the diameter at which the variable design point method takes over from the one-foot method."]'::jsonb, 2, 'The message is quoted as the engine writes it, because that is the sentence a user reads on the screen, and it names the failure it exists to prevent.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 11, 'A tank is designed on its product alone, and the product has a gravity of 0.550000. What has gone wrong?', '["Nothing, as long as the product gravity is above the crossover of 0.931727, because above that gravity the product is the governing condition on the bottom course anyway.", "The shell is thinner than the hydrostatic test will demand of it, and the test is not optional.", "The thickness comes out too great rather than too small on a light product.", "The shell is sound but the courses are counted wrongly, because the course count follows the product head rather than the shell height when the design case governs."]'::jsonb, 1, 'On the sweep the design thickness at a gravity of 0.550000 is 0.129233 in where the test asks for 0.218926 in, and the required thickness is the larger of the two.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 12, 'The floor on this tank is lowered until no course is governed by it any more. Which of the engine''s notes stops being written?', '["The note about the one-foot method, since that note is attached only where a computed condition rather than a stated floor is what decides a course of the shell.", "The note that names the provenance of the stated minimum, since a minimum that governs nothing is no longer a value in force.", "The note about the water test, since a lowered floor moves the crossover gravity and takes the bottom course with it.", "The one beginning `neither the product nor the water test needs this much plate`, because it is written where the stated minimum governs."]'::jsonb, 3, 'That note names the value in force and the condition it beat, so it belongs to the rows where the required thickness sits above both computed thicknesses.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 13, 'What does the note about the one-foot method oblige an engineer to do?', '["Re-run the shell at the variable design point method, which the engine offers as a second mode for any tank standing above the diameter limit the standard sets.", "Treat the thickness as an extrapolation, in the way a thermal rate above the stated capacity limit is labelled an extrapolation.", "Check the tank diameter against the standard, because the diameter at which the variable design point method is required is not carried here.", "Add a corrosion allowance to every course, since the one-foot method returns a bare thickness."]'::jsonb, 2, 'The relation implemented is the one-foot method and it is implemented correctly. What the package cannot tell you is where the method''s own range ends.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 14, 'The bottom course of this tank carries a head of 34.600000 ft while its own top is at 8.000000 ft. How is the head being measured?', '["From the design liquid level down to a point in the course, so the head is a depth below the liquid rather than a course height.", "From the bottom of the tank up to the top of the course, which is why the head on the top course is the smallest.", "From the design liquid level down to the top of the course below, which is what the one-foot offset in the name refers to, so each course is measured against the course lying beneath it.", "From the top of the shell down to the bottom of the course, so the head is the plate standing above it."]'::jsonb, 0, 'The head on course 5 is 2.600000 ft where the course itself runs from 32.000000 ft to 36.000000 ft, which only makes sense as a depth below the liquid.'),
  ('metering', 'advanced', 'module', 'm02-the-shell-and-what-governs', 15, 'What is the limit of the bisection method this module teaches?', '["It cannot resolve a boundary more finely than the sweep rows either side of it, so a crossover is only ever known to the width of the coarsest interval the table happens to carry.", "It finds a boundary the engine has, and there is nothing to converge on where the engine refuses to answer at all.", "It works on a returned number and not on a returned word, so a result that answers in a word has to be turned into a number before a boundary can be found in it.", "It assumes the word changes only once, so a second change further along is hidden."]'::jsonb, 1, 'The crossover at 0.931727 was found by asking the engine which side of the boundary it was on, and a quantity the engine withholds offers no such answer to narrow.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 1, 'On this tank the fill rate is 2480.0000 bbl/hr and the draw rate is 640.0000 bbl/hr. Which of the four venting terms does the fill rate set?', '["The movement inbreathing of 3593.3333 scfh, because a tank taking liquid has to pull air in behind the pump that is filling it and the rate is what sets how fast.", "The thermal outbreathing of 11765.0907 scfh, because the arriving liquid warms the vapour space and the warming is what drives the thermal term outward.", "The movement outbreathing of 13924.1667 scfh, because liquid entering pushes vapour out ahead of it.", "The total inbreathing of 23201.8178 scfh, because a filling tank is the case that governs the inward direction on a fixed-roof tank of this size."]'::jsonb, 2, 'Movement inbreathing is set by the draw rate and comes back as 3593.3333 scfh, and the two movement terms are the ones an operating decision can move within the hour.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 2, 'The thermal inbreathing of this tank is returned as 19608.4845 scfh. What is it keyed to?', '["The nominal capacity in barrels, at a stated rate of 1.000000 scfh of air per barrel and a latitude factor of 1.000000.", "The working capacity of 18845.9323 bbl, which is the volume of liquid that can actually move in and out of the tank in service.", "The vapour space above the liquid, taken as the cross section over the height between the design liquid level and the top of the shell.", "The draw rate of 640.0000 bbl/hr, converted to a rate of air at the stated thermal rate per barrel."]'::jsonb, 0, 'The engine returns the rate per barrel and the latitude factor beside the answer so the basis of the inbreathing figure sits in the same result that carries it.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 3, 'Thermal outbreathing comes back as 11765.0907 scfh for a low volatility product and 19608.4845 scfh for a high volatility one. What is the engine saying?', '["That the high volatility case has been extrapolated above the stated capacity limit of 20000.0000 bbl, which is why it comes back equal to the nominal capacity in barrels.", "That the low volatility case is carried at a stated fraction of the thermal rate, which is one of this engine''s own choices.", "That a high volatility product raises the latitude factor above 1.000000, and the outbreathing follows that factor while the inbreathing does not.", "That the two figures are the outbreathing at two different fill rates, since the volatility of the product decides which of the movement terms is added in."]'::jsonb, 1, 'The engine states the basis: one scfh of air per barrel of capacity for an uninsulated tank at a latitude factor of 1, with the low-volatility outbreathing at 0.6 of it.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 4, 'At the stated rates the engine returns a total outbreathing of 25689.2574 scfh and a total inbreathing of 23201.8178 scfh. What may a writer say about the pair?', '["That the outbreathing stands at twice the inbreathing, since 2.000000 is the ratio this pair is printed at on the relation line the digest carries for the two directions.", "That the two are close enough to be treated as one figure, which is why the engine forms a single predicate rather than reporting each direction separately.", "That the inbreathing is the larger of the two by 2487.4395 scfh, since the relation prints the difference as the first value less the second.", "That the difference is 2487.4395 scfh and the ratio is 1.107209, both quoted from the relation line the digest prints."]'::jsonb, 3, 'The relation carries the two values, their difference and their ratio, and a comparison is only ever stated where a relation line states it.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 5, 'Why does the engine form one predicate for the governing direction rather than letting the label, the warning and the sizing step each ask the question?', '["Because the two totals are computed in different units, and one place in the engine holds the conversion between them.", "Because a predicate evaluated once can be cached, which is what keeps a sweep of the draw rate cheap enough to bisect at the resolution the crossover needs.", "Because three separate questions can answer differently at the tie, which is exactly where a designer is choosing between the two cases.", "Because the warning has to fire before the totals are known, so the predicate is formed early and the two totals are checked against it afterwards."]'::jsonb, 2, 'Two expressions disagreed at the tie and the label said vacuum while the warning stayed silent, so the decision is made once and everything else reads it.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 6, 'Down the draw rate sweep the outbreathing column sits at 25689.2574 scfh on every row. Why?', '["The draw rate does not appear in either outbreathing term, so moving it cannot move that column.", "The outbreathing has already been capped at the high volatility total.", "The sweep holds the fill rate at 2480.0000 bbl/hr, which fixes every term.", "The engine carries the outbreathing from the first row of the sweep."]'::jsonb, 0, 'Movement outbreathing is set by the fill rate and thermal outbreathing by the capacity, and the inbreathing column climbs from 19608.4845 scfh to 33083.4845 scfh across the same rows.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 7, 'Between which two rows of the draw rate sweep does the governing word change?', '["Between 640.0000 bbl/hr and 900.0000 bbl/hr, the stated rate and the row above it.", "Between 900.0000 bbl/hr and 1200.0000 bbl/hr, and the crossover is reported at 1083.0319 bbl/hr.", "Between 1200.0000 bbl/hr and 1600.0000 bbl/hr, where the inbreathing passes 25689.2574 scfh and the vacuum warning starts to be written on the result.", "Between 1600.0000 bbl/hr and 2400.0000 bbl/hr, at the top of the sweep."]'::jsonb, 1, 'The engine returns pressure (outbreathing) at 900.0000 bbl/hr and vacuum (inbreathing) at 1200.0000 bbl/hr, which is what puts the crossover inside that interval.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 8, 'What does the engine write when the vacuum direction governs?', '["A warning that the inbreathing total has passed the outbreathing total and that a pressure vacuum valve should be resized for the larger of the two directions before the next draw.", "A warning that the draw rate has passed the crossover of 1083.0319 bbl/hr and that a rate above the crossover is outside the range these movement relations were fitted over.", "A warning that the thermal inbreathing is an extrapolation, because a tank drawn down hard is a tank whose vapour space is changing faster than the stated rate per barrel allows.", "`vacuum governs. A tank is a thin-walled vessel designed for inches of water column, and an undersized vacuum vent will pull it flat during a cold rainstorm on a draining tank. This is the case that destroys tanks`"]'::jsonb, 3, 'The message names the mechanism and the weather together, because a cold rainstorm drives the thermal term inward while a draining tank drives the movement term inward on the same tank.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 9, 'A crossover draw rate of 1083.0319 bbl/hr is quoted in a report on another tank of the same design. What is wrong with that?', '["Nothing, provided the second tank shares the diameter and the shell height.", "It is quoted at the wrong precision for a movement rate in this course.", "It is a property of this tank at this fill rate, so changing the fill rate alone moves it.", "It was found by bisection, so only the bracketing rows may be quoted."]'::jsonb, 2, 'The outbreathing total of 25689.2574 scfh is what the inbreathing has to overtake, and that total is set by the fill rate and the thermal terms of this tank.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 10, 'What does the digest print about the thermal inbreathing of this tank with insulation applied?', '["A relation giving 19608.4845 scfh uninsulated, 4902.1211 scfh insulated, a difference of 14706.3634 and a ratio of 4.000000.", "That insulation removes the thermal term altogether, so an insulated tank breathes on its movement terms alone and the inbreathing falls to 3593.3333 scfh.", "That insulation is applied as a latitude factor below 1.000000, so the credit shows up in the same field the latitude factor is returned in.", "That the credit is read from the standard for a documented insulation system."]'::jsonb, 0, 'The credit applied is 0.25 and the engine says it is its own stated choice rather than a value read from the standard.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 11, 'The engine is asked for the venting of a tank holding 250,000 bbl. What does it do?', '["It refuses, because the published table above that capacity is not carried here and a rate the package cannot source is withheld rather than guessed at.", "It returns a figure and labels it an extrapolation above the 20,000 bbl at which this package stops claiming the thermal rate is proportional to capacity.", "It returns the thermal rate at the stated capacity limit of 20000.0000 bbl instead, so a large tank is held at the last capacity the proportionality was claimed over.", "It returns the figure with no note at all, because the proportionality is a property of the relation rather than a range the package has to defend."]'::jsonb, 1, 'A study is not blocked and nobody buys a vent on the figure, because the engine says the inbreathing must be checked against API 2000 before a vent is bought.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 12, 'Moving a product from low volatility to high volatility at the same fill rate does what to the movement outbreathing?', '["It leaves it at 13924.1667 scfh, because volatility enters the thermal term alone.", "It takes it to 19608.4845 scfh, the high volatility thermal figure.", "It takes it to 25689.2574 scfh, the total outbreathing on this tank.", "It takes it from 13924.1667 scfh to 27848.3333 scfh, a ratio of 2.000000 on the relation line."]'::jsonb, 3, 'The incoming liquid also evaporates, so the vapour space has to expel the displaced volume and the new vapour together.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 13, 'Which part of a venting result is the part a reviewer will challenge?', '["The totals, because adding a thermal term to a movement term crosses two mechanisms with different clocks and the sum is the step a reviewer can check independently.", "The governing word, because a label carries no basis a reviewer can go back to.", "The factors, because the rate per barrel, the latitude factor and the credits are the engine''s own stated choices.", "The capacity, because the whole thermal side is keyed to it and an error there is multiplied through."]'::jsonb, 2, 'The engine returns the rate per barrel at 1.000000 and the latitude factor at 1.000000 and says the factors are not cited to a document in this repository.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 14, 'At the stated rates on this tank, which total would a vent be sized against?', '["The total inbreathing of 23201.8178 scfh, because the inward direction has the unforgiving failure mode and a vent is always sized on the worse consequence.", "The total outbreathing of 25689.2574 scfh, because the engine returns pressure (outbreathing) as the governing case.", "The sum of the two totals, because a vent has to pass whatever is happening at once.", "The thermal inbreathing of 19608.4845 scfh, because the weather terms run all year."]'::jsonb, 1, 'The two totals are 25689.2574 scfh and 23201.8178 scfh, and the governing case the engine returns is the one a vent is sized against.'),
  ('metering', 'advanced', 'module', 'm03-normal-venting', 15, 'What would have to become true of the two totals for the engine to return vacuum on this tank?', '["The total inbreathing would have to overtake the total outbreathing, which on the sweep happens once the draw rate is high enough.", "The thermal inbreathing would have to overtake the thermal outbreathing, which is the pair the governing predicate is formed from.", "The movement inbreathing would have to overtake the movement outbreathing of 13924.1667 scfh, with the thermal terms left out of the comparison.", "The inbreathing would have to reach twice the outbreathing, which is the margin the engine applies before it changes the word it returns."]'::jsonb, 0, 'At 1200.0000 bbl/hr the inbreathing is 26345.9845 scfh against an outbreathing of 25689.2574 scfh, and that is the first row on which the word is vacuum.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 1, 'This tank has a shell height of 36.000000 ft and a design liquid level of 34.600000 ft, and the fire result returns an effective wetted height of 30.000000 ft. What has happened?', '["The standard''s own height limit has capped the height that counts, so the shell above it takes no credit for heat from the fire.", "The height has been taken to the design liquid level and then reduced by the course height of the top course.", "The engine has used the height of the vapour space rather than the height of the liquid.", "The height has been cut because the wetted area fell into a band with its own height basis."]'::jsonb, 0, 'The wetted area of 5881.0614 ft2 was formed on 30.000000 ft rather than on 34.600000 ft, which is why the two figures are returned beside one another.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 2, 'Which sentence does the engine write when the wetted height cap binds?', '["A note saying the wetted area has been limited to the area of the band the tank falls in, so a taller tank cannot be moved into a higher band by its height alone.", "A note saying the level used for fire exposure is the design liquid level.", "A note saying the shell above the cap is credited at a reduced rate.", "`only the wetted shell below 30 ft counts for fire venting (API 2000): a flame does not reach higher in the standard''s basis`"]'::jsonb, 3, 'The basis assumes a pool fire around the tank, and the relation was established for the shell a flame of that kind envelops.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 3, 'The engine is asked for the fire case on a tank with a 48 ft liquid column. What effective wetted height comes back?', '["48 ft, because the cap applies to the area rather than to the height and a taller liquid column is wetted shell like any other shell.", "34.600000 ft, because the engine falls back to the design liquid level of the geometry it was given when a column exceeds the cap.", "30.000000 ft, the same as on this tank, because the cap binds on both.", "A refusal, because a liquid column above the cap is outside the basis the heat input relation was established over."]'::jsonb, 2, 'A taller tank does not get a larger fire duty out of its extra height, which is why the returned height is printed beside the area.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 4, 'Where does this tank sit in the heat input bands, and what duty comes with it?', '["In the band from 1000 to 2800 ft2, at a duty of 14089436.4220 Btu/hr, which is the duty the engine returns at the top of that band.", "In the band above 2800 ft2, at a fire duty of 25892440.2513 Btu/hr with an environment factor of 1.000000.", "In the band from 200 to 1000 ft2, at a duty of 9937139.0067 Btu/hr.", "In the band above 2800 ft2, at a duty of 19646433.0614 Btu/hr, which is the figure the sweep returns for the largest area it was run at."]'::jsonb, 1, 'The wetted area of 5881.0614 ft2 puts the tank in the top band, and 19646433.0614 Btu/hr belongs to the sweep row at 4200.0000 ft2.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 5, 'Across the whole sweep of wetted areas the vent column comes back null on every row. What does that tell a reader?', '["That the sweep was run with the vent calculation switched off.", "That a vent capacity is returned only below an environment factor of 1.000000.", "That the refusal is not a property of one tank: the engine returns no vent capacity at any wetted area.", "That the vent capacity is returned in a separate result the sweep does not print, so a caller who needs it asks the fire venting function a second time."]'::jsonb, 2, 'Ten swept areas return ten duties and not one capacity, so the null column is the behaviour itself rather than a gap in how the rows were made.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 6, 'Why does the engine refuse to turn the duty it has just computed into a required vent capacity?', '["`the required vent capacity is withheld. Turning this duty into scfh of air equivalent needs the API 2000 air-equivalence relation, and this package does not carry it. The relation that used to be here divided by the square root of an absolute temperature beside a packaged field constant, which cannot both be right, and the two plausible forms of it differ by a factor of about 24. An emergency vent sized 24 times too small is how a tank is destroyed, so no figure is offered here. Size the vent from API 2000 against the heat input above, or from the vent manufacturer''s certified capacity curve`", "Because the duty of 25892440.2513 Btu/hr is itself an extrapolation above the top band edge at 2800.0000 ft2, so any capacity taken from it would carry that extrapolation forward into a vent size.", "Because the environment factor of 1.000000 is the case with no credit taken, and the engine will not convert a duty into a capacity until a drainage credit has been justified by the caller.", "Because the conversion depends on the vapour the product makes under fire exposure, and this package takes no vapour pressure at all in the fire calculation."]'::jsonb, 0, 'The message names the relation it needs, says the package does not carry it, says what is wrong with the candidate it will not use, and gives the reader two routes to the answer.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 7, 'What makes the factor of about 24 decisive, when engineering works with uncertain quantities all the time?', '["A factor of that size cannot be carried through the units, so the two forms would give answers in different units and only one of them could be quoted as scfh of air.", "A disagreement of that size means one of the two forms has an arithmetic error in it.", "It is above the ratio of 3.333333 the environment factor relation prints, which is the largest movement the engine will accept in a fire result before it stops answering.", "No margin policy covers being wrong by that much in the unsafe direction on the last line of defence."]'::jsonb, 3, 'A duty known to a few percent supports a purchase. Two forms differing by a factor of about 24 mean picking one is being wrong by that factor whenever the other form is right.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 8, 'Why does the engine export the withholding message as a named constant?', '["So a caller can switch the refusal off and receive the figure from whichever of the two plausible forms the package was configured with at the time of the call.", "So a screen cannot print a blank where the vent should be, and the constant and the returned reason are the same string.", "So the message can be translated once for the interface.", "So the register has a constant to count against."]'::jsonb, 1, 'A blank looks like a tool that broke, a zero looks like a vent of no capacity, and only the sentence reads as a deliberate refusal with a route attached.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 9, 'The refusal names two routes to a vent capacity. Which returned figure does each of them start from?', '["The standard starts from the fire duty and the manufacturer''s curve starts from the wetted area of 5881.0614 ft2, since a certified curve is published against the area it protects.", "The standard starts from the wetted area and the manufacturer''s curve from the effective wetted height of 30.000000 ft, which is what a certified capacity curve is indexed on.", "Both start from the fire duty, which on this tank is 25892440.2513 Btu/hr.", "Both start from the heat input band, because the band is what decides which relation a capacity is read against in either route."]'::jsonb, 2, 'The refusal says to size the vent from API 2000 against the heat input above, or from the vent manufacturer''s certified capacity curve, so the refusal costs one step rather than the calculation.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 10, 'The engine carries four fire heat input bands. What was that count taken over, and what made a band count?', '["The band names returned across the swept wetted areas, with one count for each distinct band string returned over that sweep.", "The rows of the band edge table, with one count for each edge the bisection of the band name found between one relation and the next one above it.", "The relations in the engine source, with one count for each heat input expression written there.", "The wetted areas in the sweep, with one count for each area that returned a duty."]'::jsonb, 0, 'A count is not checkable without its tree and its rule, and the rule here is what explains why ten swept rows produce four bands rather than ten.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 11, 'At the edge where the 1000 to 2800 ft2 band gives way to the band above it, the digest prints a duty of 14091137.6199 Btu/hr below the edge and 14089282.6189 Btu/hr above it. Why print both?', '["So a reader can interpolate between the two and recover the duty at any area inside either band without calling the engine again for it.", "So the behaviour of the duty across a change of relation can be read rather than assumed.", "So the edge itself can be located, since the wetted area at which the change happens is not returned by the engine and has to be inferred from the two duties.", "So the discontinuity can be corrected, because a designer quoting a duty near an edge is expected to blend the two relations across it."]'::jsonb, 1, 'Each edge was found by bisecting the band name the engine returns, and the two duties are printed at 2800.0000 ft2 so a reader can see what the change of band does.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 12, 'What does the engine say about an environment factor above 1?', '["That it is accepted and applied, because a tank with no drainage and no spray is exposed to more than the bare relation assumes and the factor is the place that is carried.", "That it is treated as 1.000000 with a note beside the returned duty.", "That it moves the tank into the band above its own wetted area band.", "That it would be a penalty, and the factor is a credit for drainage, insulation or a water spray lying between 0 and 1."]'::jsonb, 3, 'The bound is the engine''s own sentence: the relation carries a credit and does not carry a penalty.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 13, 'The digest prints the fire duty on this tank with and without a stated drainage credit. What does that relation carry?', '["A ratio of 0.300000, since that factor is what produced the second value.", "A difference of 18124708.1759 Btu/hr against the duty at the top of the band.", "25892440.2513 Btu/hr with no credit, 7767732.0754 Btu/hr at a factor of 0.300000, a difference of 18124708.1759 and a ratio of 3.333333.", "A ratio of 24, the factor the engine names for the two forms it will not use."]'::jsonb, 2, 'The relation line gives both values, their difference and their ratio, and a credit of that size has to be earned by drainage, insulation or a spray that exists and is maintained.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 14, 'A datasheet carries the fire duty in the field where the vent capacity belongs. What is wrong with that?', '["A duty is a heat input in Btu an hour and a vent is specified in scfh of air equivalent, so the entry will eventually be read as a capacity.", "Nothing, provided the duty is labelled, because a reviewer checks the units.", "The duty is the wrong figure to carry forward to the standard in any case.", "The duty was computed with no drainage credit, so the entry is conservative."]'::jsonb, 0, 'The fire duty of 25892440.2513 Btu/hr is what the standard''s own relation needs, and putting it in a capacity field is how a withheld figure gets invented downstream.'),
  ('metering', 'advanced', 'module', 'm04-the-fire-case-and-the-withheld-vent', 15, 'What is the general rule this module wants a reader to carry into every package they use afterwards?', '["A package should return its best estimate with the uncertainty attached, because a reader who is given a range can apply their own margin to it.", "Withholding beats guessing whenever the plausible alternatives differ by more than a rounding.", "A package should refuse wherever a figure is not traceable to a document.", "A package should return the figure and the warning together, in the way a thermal rate above the stated capacity limit is returned and labelled."]'::jsonb, 1, 'When you meet a null with a reason beside it, read the reason, find the size of the disagreement, and decide which kind of argument you are in.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 1, 'The engine returns the annual loss on this tank as 77142.8167 lb/yr and again as 38.5714 short tons/yr. Why both?', '["Because the two figures come from different relations, one over the vapour space and one over the throughput, and the units keep the two apart in the result.", "Because an operations engineer works in one unit and an emissions inventory is filed in the other, and a conversion done in correspondence eventually arrives wrong.", "Because the emissions figure carries a control efficiency and the operations figure does not, so the two are the same loss before and after control.", "Because the short tons figure is the total and the pounds figure is the standing half, which is the half a cost estimate is built on."]'::jsonb, 1, 'Returning both renderings makes the conversion part of the result rather than part of the correspondence, and the two rows are the same quantity.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 2, 'What is the difference in mechanism between the standing loss and the working loss?', '["Standing loss is what a tank loses through the shell and the roof seams, and working loss is what leaves through the vent while the tank is breathing on the weather.", "Standing loss is the loss at zero throughput and working loss is the loss above the design liquid level, so the two are the same relation at two levels.", "Standing loss is what evaporates and working loss is what wets the shell.", "Standing loss is breathing while nothing moves, and working loss is displacement by liquid coming in."]'::jsonb, 3, 'The standing half depends on the size of the vapour space and how much product vapour it holds, and the working half depends on throughput.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 3, 'The digest prints a relation over the two halves of the annual loss. What does it carry?', '["A difference of 70067.5951 lb/yr, since a difference between two losses is printed as a magnitude and the sign is carried by the order of the two rows.", "A ratio of 0.048062 formed as the working loss over the standing loss.", "The standing loss at 3537.6108 lb/yr, the working loss at 73605.2059 lb/yr, a difference of -70067.5951 and a ratio of 0.048062.", "A ratio taken against the total of 77142.8167 lb/yr rather than against a half."]'::jsonb, 2, 'The relation prints the standing loss first, so the difference of -70067.5951 is the first value less the second and the ratio of 0.048062 runs in the same order.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 4, 'Why does this module tell a reader to look at the split before the total?', '["Two tanks with the same annual loss and opposite splits are two different problems with two different answers.", "Because the total is in pounds a year and the two halves in short tons a year.", "Because the total is the figure an emissions inventory takes and the halves are the figures a cost estimate takes, so the audience decides which to read.", "Because the total carries the control efficiency and the halves do not."]'::jsonb, 0, 'Control equipment does not treat the two halves alike, so on a total of 77142.8167 lb/yr the split is what tells you which family of equipment is worth pricing.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 5, 'The engine returns a vapour space expansion factor of 0.042556 and a saturation factor of 0.654638 beside the loss. What are they for?', '["So the two can be multiplied together to recover the standing loss.", "So a reader can tell which factor an input moved, rather than watching a total change and guessing why.", "So the two can be quoted on their own as screening figures for a tank of this kind, in the way a rate per barrel of capacity is quoted for venting.", "So a reviewer can check the two against the published tables."]'::jsonb, 1, 'A loss figure is a product of several factors, and a reader who has only the total has to guess which one an input moved.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 6, 'A product with a true vapour pressure of 15.4 psia is submitted to the loss calculation. What does the engine return?', '["`a true vapour pressure of 15.4 psia is at or above the stated atmospheric pressure of 14.7 psia: the product boils at ambient and this is not a fixed-roof tank problem. It needs a pressure vessel or a refrigerated tank, and these relations do not apply to it`", "A standing loss of zero with a note saying the expansion factor has collapsed, and a working loss computed normally, so the total is the working half alone.", "A total loss computed from the working half with the standing half omitted, and a warning that the figure is an extrapolation above the range of the relations.", "A refusal naming the control efficiency, because a product at atmospheric pressure cannot be controlled to any stated efficiency by a recovery unit."]'::jsonb, 0, 'The refusal redirects as well as declining: it names the equipment the question actually needs rather than only saying the calculation cannot be done.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 7, 'Which half of the loss carries the denominator that fails on a product boiling at ambient?', '["The working loss, because the throughput of 484000.0000 bbl a year is divided by the vapour pressure to form the turnover effect in that half.", "Both halves, because the vapour density of 0.027086 lb/ft3 is formed from the vapour pressure and it multiplies each of the two halves in turn.", "The standing loss, through the vapour space expansion factor.", "Neither half, because the relations are written on the difference between the two pressures rather than on a quotient of them."]'::jsonb, 2, 'The expansion factor carries the difference between atmospheric pressure and the vapour pressure in a denominator, so at or above atmospheric there is no standing loss to return.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 8, 'What would a package that returned only the total show for a product that boils at ambient?', '["A refusal, because a total cannot be formed while one of its two components is undefined and the sum would inherit the undefined component.", "A zero, because the working half is a fraction of the standing half.", "A total far above the real one, because the expansion factor would grow without limit as the vapour pressure approached the atmospheric pressure.", "A number that looked like a loss, because the working half would still produce one."]'::jsonb, 3, 'A reader seeing only the sum has no way of knowing that one of its components was undefined, which is a good argument for engines returning their components.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 9, 'What does the engine say about the turnover side of the working loss?', '["That a turnover count is taken as an input and applied through the published factor, which is why the throughput appears twice in the working half.", "That it is the stated workingTurnoverFactor, because AP-42''s turnover factor Kn is not carried and a turnover count is not an input here.", "That the turnover effect is read from the same table the saturation factor is read from.", "That the turnover effect is withheld by name, in the way a required emergency vent capacity is withheld, so no working loss is returned."]'::jsonb, 1, 'An input a package cannot honour should not be accepted, because accepting it moves the error out of the engine and into a user''s head.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 10, 'The engine is asked for the saving from a control device and no efficiency is supplied. What comes back?', '["The saving at the lowest efficiency in the table, which is 60.000000 percent, so a caller who omits the figure is given the most conservative of the cases.", "A saving of zero with the total of 77142.8167 lb/yr carried through as the remaining loss, which is the uncontrolled case and the safe default to report.", "`a control efficiency is needed: leaving it out is not the same as saying zero`", "A saving at a stated default efficiency, with the default named."]'::jsonb, 2, 'An omitted input is unknown and a zero is a claim, and a package that treats the first as the second has invented an answer on the user''s behalf.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 11, 'A control efficiency of 140 percent is submitted. What does the engine do with it?', '["It refuses, because an efficiency lies between 0 and 100.", "It clamps the figure to 100.000000 percent and returns the whole of the loss as saved, with a note saying the input was above the range and was limited.", "It applies the figure and returns a remaining loss below zero, which is the sign a downstream reader is expected to catch before quoting the saving.", "It returns the saving at the highest efficiency in its own table, which is 98.000000 percent for a vapour recovery unit on a tank of this kind."]'::jsonb, 0, 'The two loss control refusals are a pair: one fires on an input that is present and impossible, and the other on an input that is absent.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 12, 'At a control efficiency of 90.000000 percent on this tank, what does the engine return?', '["A saving of 73285.6759 lb/yr and a remaining loss of 3857.1408 lb/yr, which is the row a floating roof is customarily credited with on a tank of this throughput.", "A saving of 57857.1125 lb/yr and a remaining loss of 19285.7042 lb/yr, since the saving is applied to the working half of the loss and not to the standing half.", "A saving of 75599.9604 lb/yr and a remaining loss of 1542.8563 lb/yr, because the efficiency is applied to the total and then again to the standing loss.", "A saving of 69428.5350 lb/yr and a remaining loss of 7714.2817 lb/yr."]'::jsonb, 3, 'The table answers a conditional question: given an efficiency, the saving and the remaining loss both follow from the total of 77142.8167 lb/yr.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 13, 'Where do the efficiencies in the control table come from?', '["They are computed from the split between the two halves of the loss, since a device that works on one half can only save the share that half carries.", "They are typed, because an internal floating roof customarily saves 60 to 90 percent and a vapour recovery unit 90 to 98 percent, and both are equipment and operating questions.", "They are read from the vendor curve the package carries for each device family, which is why the table stops at the highest certified figure.", "They are the efficiencies at which the remaining loss falls below a reporting threshold, which is what makes them the rows worth printing."]'::jsonb, 1, 'The engine supplies the arithmetic and declines to supply the efficiency, which comes from a vendor quotation, a performance test or an operating history.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 14, 'The vapour space volume comes back as 12844.2382 ft3. What is it?', '["The volume between the design liquid level and the top of the shell, which is the space a fixed roof leaves above a tank filled to its design level.", "The volume of vapour that leaves the tank in a year, which is what the annual throughput of 484000.0000 bbl displaces out of the roof space.", "The same cylinder the rest of this tier works on, taken over the vapour space height of 4.200000 ft.", "The volume the expansion factor of 0.042556 is applied to twice a day."]'::jsonb, 2, 'It is one more answer this tier takes out of the same geometry, beside the capacity, the shell and the wetted area.'),
  ('metering', 'advanced', 'module', 'm05-losses-and-what-control-saves', 15, 'Why does this tier put evaporative losses in the same module as money and emissions?', '["Because what leaves the roof space is product that was bought and a release that has to be reported, and the two are the same arithmetic.", "Because an emissions inventory is filed on the standing half and a cost estimate is built on the working half.", "Because the loss relations take a price per barrel as an input alongside the throughput.", "Because the control efficiencies in the table are set by the reporting threshold rather than by the equipment."]'::jsonb, 0, 'The engine returns 77142.8167 lb/yr and 38.5714 short tons/yr for the same loss, so reading the result twice costs nothing.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 1, 'This course calls and proves 28 distinct refusals. What was that count taken over, and what made a call count?', '["The assertion list the generator built while it ran, filtered to the ones labelled a refusal, with one count per distinct assertion text, each asserting that the engine returned an error key.", "The refusal messages the three engines export as named constants, with one count for each distinct message.", "The guard clauses written in the three engine sources, with one count for each clause that can return early.", "The inputs the generator rejected before calling anything, with one count for each input rejected."]'::jsonb, 0, 'A list compiled by reading the source would be a list of refusals somebody believed were reachable, which is a weaker claim than one that provoked every case.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 2, 'What rule decides whether a call this course made counts as one of its 238 successes?', '["The result matched a golden case for the same function, which is what separates a call that ran from a call that ran correctly.", "The result carried a figure the digest went on to print, so a call whose output is never quoted anywhere is not counted as a success.", "The result carried no error key and no non-finite number in it.", "The result carried no warning and no note, since a call that returns a caveat is neither a refusal nor a clean success."]'::jsonb, 2, 'The successes and the refusals are counted over the same assertion list filtered two ways, and the rule is what tells the two halves apart.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 3, 'A generator labels a row a refusal and then calls a case that succeeds. What is the shape of that defect and what stops it here?', '["The numbers would be invented rather than returned, so a sweep of the literals against the engine finds them and the build stops there.", "Real engine output would print under a false sentence, and nothing numeric could see it, so the file writes nothing at all if any label disagrees with its call.", "The row would carry a null where a figure belongs, which the reproducibility check catches on the second build of the file.", "The count of refusals would disagree with the count of successes, and the two are asserted to add to the number of calls made."]'::jsonb, 1, 'When you assert a behaviour and print evidence of it, have something check that the evidence is evidence of the thing you asserted.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 4, 'The register in this course holds fifteen items. What makes something an item?', '["The item is a table or a correlation named in a standard that any of the three engines would need in order to answer a question a user might ask of it.", "The item is named in a standard one of the three engines cites, and the register lists every citation the package carries between its three modules.", "The item is a figure this course prints but does not grade, which is why no capstone field rests on one.", "The engine states, in its own source or its own returned text, that the package does not carry it, does not cite it, or refuses to answer it."]'::jsonb, 3, 'Two of the fifteen are outright refusals to answer, where the engine returns a refusal or a withheld flag in place of a number.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 5, 'This course sorts the register three ways: held (the rows the register marks NOT CARRIED), stated and withheld. What is the difference?', '["Held is a value the caller supplies, stated is a value the standard supplies, and withheld is a value the engine computes and declines to return to a screen.", "Held is a figure returned with a warning, stated is a figure returned without one, and withheld is a figure returned as a null with no reason beside it.", "Held is absent and the engine carries on where it can, stated is a value the package chose or was handed and names, and withheld is a question it will not answer.", "Held means the item is carried but not cited, stated means it is cited but not carried, and withheld means it is neither carried nor cited anywhere."]'::jsonb, 2, 'A held item means go and look it up, a stated item means check whose number this is, and a withheld item means the answer is not available from here at any price.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 6, 'Which two items in the register are the outright refusals?', '["The straight-run requirement for two elbows in different planes, and the relation that turns a fire duty into a required vent capacity.", "The minimum shell plate thickness band table, and the diameter above which the variable design point method takes over from the one-foot method.", "The turnover factor Kn, and the thermal venting table above the capacity at which the package stops claiming proportionality.", "The ISA Reynolds number factor, and the noise prediction the engine calls an indication rather than a prediction."]'::jsonb, 0, 'The register proves both by calling them: straightRunDiameters returns withheld true for two elbows in different planes and fireVenting returns ventWithheld true at every wetted area.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 7, 'Why does the register prove its two refusals by calling them rather than by citing the engine source?', '["Because the engine sources are vendored and a citation into them would pin a line number that moves on the next repair.", "A refusal read off the source is one somebody believes is reachable, and calling it shows the flag and the null coming back.", "Because a source comment is provenance and a course may not quote one, so the call is the only route to the text of the message.", "Because the two refusals are raised by three different functions between them, and a citation could only name one of the three."]'::jsonb, 1, 'fireVenting returns ventWithheld true and a null vent capacity at every wetted area, which is a behaviour rather than a claim about the source.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 8, 'The tank engine''s own refusals are listed by the function that raises them. Which pair of functions raises two each?', '["evaporativeLosses and fireVenting, which are the two tank functions that stop on the range of a relation rather than on an input.", "tankCapacity and movementVenting, which are the two tank functions whose refusals fire on a rate or a height below zero.", "fireVenting and tankCapacity, which are the two tank functions whose refusals are proved twice over in the register itself.", "lossControl and thermalVenting."]'::jsonb, 3, 'lossControl refuses above a hundred percent and with no efficiency, and thermalVenting refuses at a latitude factor above what the package will apply and with no capacity.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 9, 'How many refusals does orificeFlow raise in this list, and what are they about?', '["Four, on a compressible flow with no static pressure, a differential above the static pressure, a bore above the pipe bore and no differential at all.", "Two, on a differential above the static pressure and on an orifice bore above the pipe bore.", "Three, on a missing differential, a missing static pressure and a missing discharge coefficient.", "One, on a differential above the static pressure, which is the only impossible input the function takes."]'::jsonb, 0, 'Every one of them was provoked, called and inspected for an error key, which is what counting a refusal requires.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 10, 'The count of counts in this course comes back as nineteen. What rule makes that number checkable?', '["One per figure the file prints that is a whole number rather than a decimal, which is how a count is told apart from a measurement.", "One per section that carries a count, so a section printing several counts contributes one to the total.", "One per call to the counting helper, which is the only way a count reaches the file at all.", "One per tree named in the file, since a count and the tree it was counted over are written together."]'::jsonb, 2, 'A count of counts is only checkable if there is exactly one route by which a count can be created, and naming the route is what tells a reader that none arrived some other way.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 11, 'Two counts on this tank are taken over the same courses array. What separates them?', '["The condition each was evaluated at, one over the design case and one over the test case.", "The governing word the engine returned, which is hydrostatic test for one count and minimum plate thickness for the other.", "The required thickness, with a course counted against the first where the thickness stands above the stated minimum plate thickness.", "The head, with the courses below the design liquid level counted in the first and the courses above it counted in the second."]'::jsonb, 1, 'Written without their rules, those two numbers are a one and a four attached to a tank, and a reader cannot tell whether they overlap or exhaust the table.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 12, 'The digest pins fifty engine strings verbatim. What does the pinning actually buy?', '["A reader can search the engine source for the string and confirm the message has not been edited since the file was built.", "A screen showing a message and an engine returning one cannot drift apart, because the pinned string is the named constant the interface reads and the engine returns on the call itself.", "A message that breaches the owner copy rule is exempted by exact text, which is what allows a contrastive to be quoted at all.", "Each was asserted to contain a fragment of its own text as the file was built, so a reworded message fails the build rather than teaching wording nobody will see."]'::jsonb, 3, 'A digest that paraphrased an error message would teach a sentence the learner will never see on the screen, and the same is true of a lesson.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 13, 'Which of these is never a source for a figure in a document about this package?', '["A message the engine returns, because a sentence is not a figure and cannot be checked against an engine output.", "A figure printed in the digest at six decimals, since a rendering is not a value.", "A comment in the engine source, because it often describes what the code did at some earlier time.", "A relation line, because a comparison is somebody''s reading of two figures."]'::jsonb, 2, 'The test is whether you can make the package produce the figure right now by calling it. A repair note and a review document are in the same position as the comment.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 14, 'A writer wants to say that one figure in this course is a fraction of another. What does the course require?', '["That the comparison was computed and printed as a relation carrying both values, their difference and their ratio.", "That both figures come from the same section of the file, so that a comparison never crosses a boundary between two engines.", "That the arithmetic is shown, so a reader can follow the subtraction or the division that produced the claim.", "That the two figures are quoted at the same precision, since a ratio between two renderings of different length is not defensible."]'::jsonb, 0, 'Your own arithmetic over two published figures is not a source, because the two may not be on the same basis, at the same condition or in the same units.'),
  ('metering', 'advanced', 'module', 'm06-the-register-and-the-refusals', 15, 'Why is a course built this way interested in refusals at all?', '["Because a refusal is the only behaviour of an engine that a course can examine without quoting a figure, so it is what a bank question can be built on.", "Because a refusal converts a silent wrong answer into a loud absent one, which stops at the person who asked.", "Because the refusals are where the three engines share a mechanism.", "Because a refusal is cheaper to check than a figure and needs no tolerance."]'::jsonb, 1, 'Each refusal sits where the relation would return a number and the number would be meaningless, and where a reader would have no way of knowing anything was wrong.'),
  ('metering', 'advanced', 'final', null, 1, 'A tank of this design is rebuilt one third larger in diameter and everything else about the service is held. Which of the tier''s answers can be left alone?', '["The venting, because the thermal rate in this package is stated per barrel of capacity and a rate per barrel is unchanged by a change of capacity.", "None of them, because the capacity, the breathing and the wetted shell all move with the geometry.", "The losses, because the working loss is driven by the annual throughput of 484000.0000 bbl and a throughput is a commercial decision rather than a geometry.", "The shell, because the one-foot method works on the head of liquid and the head is set by the design liquid level rather than by the diameter."]'::jsonb, 1, 'The capacity of 19608.4845 bbl carries the thermal terms, the shell carries the courses, and the wetted shell carries the fire duty.'),
  ('metering', 'advanced', 'final', null, 2, 'Two heights are in play on this tank when a working capacity and a fire wetted area are computed. Which pair is it?', '["The design liquid level of 34.600000 ft for the capacity, and an effective wetted height of 30.000000 ft for the area.", "The shell height of 36.000000 ft for the capacity, and the design liquid level of 34.600000 ft for the area.", "The design liquid level for both, because both quantities are taken over the liquid the tank is designed to hold.", "The shell height for both, because a tank is built to its shell and a fire reaches whatever shell is there."]'::jsonb, 0, 'The working capacity is the volume to the design liquid level, and the fire area is formed on a height the standard''s own limit has already capped.'),
  ('metering', 'advanced', 'final', null, 3, 'Both tank crossovers in this tier were found the same way. What do a gravity of 0.931727 and a draw rate of 1083.0319 bbl/hr have in common?', '["Each is a threshold the standard publishes, which the engine reproduces so a designer can see where the governing case changes.", "Each is the input at which the engine''s warning and its governing word first disagree.", "Each was found by bisecting a word the engine returns, and each is a property of this tank at these conditions.", "Each is a limit above which the engine stops answering, in the way it stops claiming proportionality above a stated capacity."]'::jsonb, 2, 'Nothing in the package publishes either figure. The shell returns a governing candidate and the venting returns a governing case, and a word that changes has a boundary in it.'),
  ('metering', 'advanced', 'final', null, 4, 'On the course table, which course is the first whose required thickness stands above both of its own computed thicknesses?', '["Course 1, at 0.218926 in, which is the thickest course on the tank and the one the hydrostatic test decides.", "Course 3, at 0.187500 in, because course 2 still has a test thickness above the floor at the head it carries.", "Course 5, at 0.187500 in, because the floor only binds where both computed thicknesses have fallen near zero.", "Course 2, at 0.187500 in against computed thicknesses of 0.163341 in and 0.166801 in."]'::jsonb, 3, 'From course 2 upward the stated minimum plate governs, and the engine returns that word on all four of those rows.'),
  ('metering', 'advanced', 'final', null, 5, 'A reviewer asks for the fire duty on this tank set against its normal venting totals. What is the correct response?', '["Give the ratio of the fire duty to the total outbreathing, since one engine returns both.", "The engine refuses the comparison, because the two cannot be compared as vent capacities while the vent capacity is withheld.", "Convert the duty of 25892440.2513 Btu/hr into scfh of air and compare it with 25689.2574 scfh.", "Compare the two after applying the environment factor of 1.000000 to the duty, which puts both figures on the same uncredited basis."]'::jsonb, 1, 'The duty is a heat input in Btu an hour and the venting totals are rates in scfh, and this package carries no relation between the two.'),
  ('metering', 'advanced', 'final', null, 6, 'The losses module works on a vapour space volume of 12844.2382 ft3. How does that figure relate to the rest of the tier?', '["It is the same cylinder as the capacity and the wetted shell, taken over the vapour space height rather than over the shell.", "It is the difference between the nominal and the working capacity in cubic feet.", "It is the volume above the design liquid level at the moment the tank is full, which is what the standing loss relation breathes on.", "It is a volume the loss relations form from the throughput rather than the geometry."]'::jsonb, 0, 'One geometry has now produced a capacity, a wetted area and a vapour space, which is why the three questions sit in one module.'),
  ('metering', 'advanced', 'final', null, 7, 'A venting calculation and a loss calculation are run on this tank. Which stated input do the two share?', '["The fill rate of 2480.0000 bbl/hr, which the working loss takes as the rate the vapour space is displaced at.", "The nominal capacity of 19608.4845 bbl, which the standing loss breathes over.", "Neither shares one: the venting takes rates in barrels an hour and the loss takes an annual throughput.", "The draw rate of 640.0000 bbl/hr, which both the movement inbreathing and the working loss are formed from."]'::jsonb, 2, 'The venting is driven by 2480.0000 bbl/hr and 640.0000 bbl/hr, and the loss by an annual throughput of 484000.0000 bbl.'),
  ('metering', 'advanced', 'final', null, 8, 'The minimum shell plate thickness in force on this tank is 0.187500 in and four courses are decided by it. What does the register say about that figure?', '["That the band table is carried and read against the tank diameter, which is how a caller is spared supplying a minimum at all.", "That the figure is withheld by name, so a caller who needs a minimum has to take it from the standard directly.", "That the figure is the engine''s own stated choice, as the thermal rate is.", "That the API 650 band table is not carried, so the minimum is a stated input and the result names the value in force."]'::jsonb, 3, 'A stated input is a shared responsibility: the engine applies it faithfully and names it, and somebody still has to check the band for this diameter.'),
  ('metering', 'advanced', 'final', null, 9, 'Which quantity on this tank is not read off the shell geometry at all?', '["The true vapour pressure of 2.370000 psia, which is a property of the product rather than of the tank.", "The vapour space volume of 12844.2382 ft3, formed out of the annual throughput.", "The wetted area of 5881.0614 ft2, which the fire case takes from the heat input band the tank lands in.", "The cross section of 3058.1520 ft2, which the engine forms from the design liquid level rather than the diameter."]'::jsonb, 0, 'One geometry gives a capacity, a wetted area and a vapour space, and the vapour pressure is a product property the loss relations are handed.'),
  ('metering', 'advanced', 'final', null, 10, 'A vapour recovery unit is quoted at 95.000000 percent on this tank. What does the engine report for it?', '["75599.9604 lb/yr saved and 1542.8563 lb/yr remaining, which is the row at the top of the customary band for such a unit.", "69428.5350 lb/yr saved and 7714.2817 lb/yr remaining, because a quoted efficiency is applied to the working half alone.", "73285.6759 lb/yr saved and 3857.1408 lb/yr remaining.", "57857.1125 lb/yr saved and 19285.7042 lb/yr remaining, because a recovery unit is credited against the standing half."]'::jsonb, 2, 'A recovery unit is customarily credited with 90 to 98 percent, and the engine says those figures are equipment and operating questions rather than results.'),
  ('metering', 'advanced', 'final', null, 11, 'The sweep returns 3980000.0000 Btu/hr at 199.0000 ft2 and 3998437.1717 Btu/hr at 200.0000 ft2. What has changed between the two rows?', '["Nothing but the area, since the duty inside a band is a straight line through the origin and the band name is a label on it.", "The band, from below 200 ft2 to 200 to 1000 ft2, so the two duties come out of two relations.", "The environment factor, which the engine lowers as the area rises so that a larger tank is not penalised twice over.", "The wetted height, which is recomputed at each area and is what moves the duty between two rows this close together."]'::jsonb, 1, 'A banded relation is a place where a small change in an input moves which relation is being used, which is why the band name is returned.'),
  ('metering', 'advanced', 'final', null, 12, 'One figure in the tank results is exact by definition and another is held at a limit the standard sets. Which pair is it?', '["The barrels per foot of shell at 544.6801, and the stated minimum plate thickness at 0.187500 in.", "The cross section at 3058.1520 ft2, and the thermal rate of 1.000000 scfh of air per barrel of capacity.", "The nominal capacity at 19608.4845 bbl, and the environment factor at 1.000000 on a tank with no credit.", "The cubic feet in a barrel at 5.614583333333333, and the effective wetted height at 30.000000 ft."]'::jsonb, 3, 'The conversion is returned as ft3PerBbl so it can be checked, and the wetted height is capped because a flame does not reach higher in the standard''s basis.'),
  ('metering', 'advanced', 'final', null, 13, 'A product with a specific gravity of 0.850000 is proposed for this tank. Which condition decides the bottom course, and what thickness comes back?', '["The hydrostatic test, at 0.218926 in.", "The product design case, at 0.199723 in, because the design thickness at that gravity stands above the stated minimum plate thickness.", "The stated minimum plate thickness, at 0.187500 in, because a gravity below the crossover leaves both computed thicknesses under the floor.", "The hydrostatic test, at 0.199723 in, because the test thickness follows the product gravity up to the crossover at 0.931727."]'::jsonb, 0, 'A gravity of 0.850000 is below the crossover of 0.931727, and the design thickness of 0.199723 in is below the test thickness of 0.218926 in.'),
  ('metering', 'advanced', 'final', null, 14, 'A cold rainstorm arrives while this tank is being drawn down. Which way do the two mechanisms push?', '["The thermal term inward and the movement term outward, which is what keeps the two directions close on a cold day.", "Both outward, because a cooling vapour space contracts and a falling level draws the roof space out behind it.", "Both inward, the thermal term on the weather and the movement term on the falling level.", "The thermal term outward and the movement term inward, so the totals move together and the governing word does not change."]'::jsonb, 2, 'That is the case the vacuum warning is written for, and on this tank the vacuum direction takes the case above a draw rate of 1083.0319 bbl/hr.'),
  ('metering', 'advanced', 'final', null, 15, 'A product whose true vapour pressure is at or above atmospheric is submitted to the loss relations. What is useful about the engine''s answer?', '["It returns the working half and withholds the standing half, so a study can proceed on the part of the loss that is still defined.", "It redirects as well as declining, by naming a pressure vessel or a refrigerated tank as the equipment the question needs.", "It reports the vapour pressure at which the expansion factor would recover.", "It converts the refusal into a warning above a stated throughput."]'::jsonb, 1, 'A fixed-roof tank sits at very close to atmospheric pressure, and a product boiling at ambient will not sit quietly in one.'),
  ('metering', 'advanced', 'final', null, 16, 'What would it take for this digest to print a row labelled a refusal under numbers from a call that actually succeeded?', '["A rebuild in another timezone, which is the drift the reproducibility check over five timezones and four locales exists to catch.", "A count whose tree and rule disagreed, which is the check that stands between a label and the evidence printed under it.", "An engine whose message had been reworded, since the pinned strings are what tie a labelled row to the call that produced it.", "Nothing would print at all, because the file is not written if any label disagrees with its call."]'::jsonb, 3, 'A numeric sweep cannot see that defect, because every figure under the false sentence would be real engine output.'),
  ('metering', 'advanced', 'final', null, 17, 'Which two things does the register call withheld by name, and what do they have in common?', '["The straight run for two elbows in different planes and the fire vent capacity, and neither is graded anywhere in this course.", "The minimum plate band table and the fire vent capacity, both noted on every call.", "The fire vent capacity and the turnover factor, and both are relations the package once carried and has since removed.", "The straight run for two elbows and the noise prediction, and both are answers the engine calls an indication rather than a figure."]'::jsonb, 0, 'A withheld item is a question the engine will not answer at all, which is a different thing from a held item, one the register marks NOT CARRIED, that it works around.'),
  ('metering', 'advanced', 'final', null, 18, 'This tank has a design liquid level of 34.600000 ft and a vapour space height of 4.200000 ft. What is each used for?', '["The level sets the working capacity and the vapour space height sets the effective wetted height the fire duty is formed on.", "The level sets the fire wetted area and the vapour space height sets the movement terms.", "The level sets the working capacity and the shell heads, and the vapour space height sets the volume the standing loss breathes on.", "The level sets the thermal terms through the capacity, and the vapour space height sets the working loss through the throughput."]'::jsonb, 2, 'Two heights on one cylinder produce a capacity of 18845.9323 bbl and a vapour space of 12844.2382 ft3.'),
  ('metering', 'advanced', 'final', null, 19, 'A lighter product is proposed for this tank and the required thickness of the bottom course does not move. What does that tell you?', '["The stated minimum plate thickness of 0.187500 in is deciding the course, which is why a change of product cannot move it.", "The water test is deciding the course, so the design thickness can fall without the required thickness following it.", "The product is above the crossover gravity of 0.931727, where the design case decides.", "The head has been held at 34.600000 ft, which fixes both computed thicknesses and leaves the required thickness where it was."]'::jsonb, 1, 'A required thickness only starts to follow the product once the design case becomes the largest of the three candidates on that row.'),
  ('metering', 'advanced', 'final', null, 20, 'Which row of the register covers the latitude factor and the insulation credit used in the venting?', '["The row for the API 650 minimum shell plate thickness band table, which covers every stated tank input the engine applies.", "The row for the turnover factor Kn, which covers every stated factor.", "The row for the relation that turns a fire duty into a required vent capacity, which is where the tank credits are registered.", "The row for the thermal venting table above the proportional limit, which is not carried or is stated."]'::jsonb, 3, 'A tank above the stated limit is warned rather than silently extrapolated, and the credits beside it are the engine''s own stated choices.'),
  ('metering', 'advanced', 'final', null, 21, 'Why does the engine refuse a required vent capacity while it will extrapolate a thermal rate on a large tank and label it?', '["Because the two plausible forms of the missing relation differ by a factor of about 24, and an undersized emergency vent looks exactly like a vent size.", "Because the fire case has no published table at all, while the thermal case has one the package could carry if a caller supplied it.", "Because a fire duty is returned at four decimals and a vent capacity would have to be returned at six, which the package cannot justify.", "Because the extrapolation is inside the range of the relation and the vent conversion is outside it, which is the line the engine draws."]'::jsonb, 0, 'A thermal rate labelled an extrapolation is a figure a designer will check. A vent capacity in a result field is one nobody checks by looking at it.'),
  ('metering', 'advanced', 'final', null, 22, 'Which of the tank engine''s refusals fires on a valid input that has left the range of the relations rather than on an impossible one?', '["tankCapacity on a fill height below zero, which is a height a tank could never stand at and a volume that could never be held.", "movementVenting on a negative fill rate, which is a rate no pump can deliver and a displacement no vapour space can take.", "evaporativeLosses on a product that boils at ambient.", "lossControl above a hundred percent, which is an efficiency no device can reach and a saving larger than the loss it acts on."]'::jsonb, 2, 'Three refusals in this tier are three kinds: an impossible input, a valid input outside the relations, and a question the package cannot source.'),
  ('metering', 'advanced', 'final', null, 23, 'What has to be printed beside a wetted area before a reviewer can audit it?', '["The band it falls in, because the relation the duty comes from is what decides the area the engine will accept.", "The height it was formed on, because an area computed on the full liquid column would look just as defensible.", "The environment factor, because a credit changes the area the fire is taken to act on before the duty is formed.", "The tank diameter, because no fire figure can be checked without the geometry."]'::jsonb, 1, 'The engine returns an effective wetted height of 30.000000 ft beside an area of 5881.0614 ft2 for exactly that reason.'),
  ('metering', 'advanced', 'final', null, 24, 'For a high volatility product the thermal outbreathing on this tank comes back as 19608.4845 scfh, which is also the capacity in barrels. Why are the two figures the same?', '["The high volatility case is capped at the capacity in barrels of the tank.", "The outbreathing is formed from the movement side and the fill rate happens to give the same figure on this tank at these rates.", "The engine returns the capacity in the outbreathing field whenever the product is high volatility, since no rate is claimed for it.", "The thermal rate is 1.000000 scfh of air per barrel of capacity, and the high volatility case carries the whole of it."]'::jsonb, 3, 'One scfh of air per barrel at a latitude factor of 1.000000 turns a capacity of 19608.4845 bbl into a rate carrying the same digits.'),
  ('metering', 'advanced', 'final', null, 25, 'A fire result is submitted with an environment factor above 1 on the grounds that the tank has no drainage at all. What happens?', '["It is refused, because the factor is a credit lying between 0 and 1 and a factor above 1 would be a penalty the relation does not carry.", "It is applied, and the duty rises above 25892440.2513 Btu/hr, which is how an exposed tank is handled in this relation.", "It is clamped to 1.000000 and the duty is returned with a note naming the value in force.", "It is accepted and the wetted area is raised instead, which moves the tank further into the band above 2800 ft2."]'::jsonb, 0, 'The engine''s sentence bounds the factor, and the relation printed with a credit of 0.300000 shows the direction a credit moves the duty in.'),
  ('metering', 'advanced', 'final', null, 26, 'Three volumes are returned on this tank. Which of them belongs to the loss calculation rather than to the capacity result?', '["The nominal capacity of 110093.4703 ft3, which is the volume the standing loss breathes over across a year of weather.", "The working capacity of 18845.9323 bbl, which is the volume the working loss is formed from through the annual throughput.", "The vapour space volume of 12844.2382 ft3.", "The cross section of 3058.1520 ft2, which is a volume per foot of shell and is what the vapour space is measured against."]'::jsonb, 2, 'It is the same cylinder taken over the vapour space height of 4.200000 ft, and the capacity result knows nothing about it.'),
  ('metering', 'advanced', 'final', null, 27, 'Which pair of figures does the relation between this tank''s two capacities carry, and in which order?', '["The working first and the nominal second, which is why the difference of 762.5522 bbl is printed without a sign.", "The nominal at 19608.4845 bbl first and the working at 18845.9323 bbl second, with a difference of 762.5522 and a ratio of 1.040462.", "The nominal in barrels and the nominal in cubic feet, which is the pair a reader checks the returned conversion against.", "The working capacity and the barrels per foot of shell, which is the pair that turns a gauge height into an inventory."]'::jsonb, 1, 'Order matters on a relation line, because the difference and the ratio are both formed as the first value against the second.'),
  ('metering', 'advanced', 'final', null, 28, 'Where the stated floor decides a course, what is the engine''s message doing for the reader?', '["It warns that the floor may be below the value the standard bands for this diameter.", "It records that the course was not evaluated at the test condition, since a test thickness below the floor is not computed at all.", "It reports the margin between the floor and the larger computed thickness.", "It explains a thickness that stands above both computed conditions, which would otherwise look like an error in the relation."]'::jsonb, 3, 'On course 4 the computed thicknesses are 0.061253 in and 0.062550 in and the required thickness is 0.187500 in, which needs a sentence beside it.'),
  ('metering', 'advanced', 'final', null, 29, 'The heat input band on a tank is reported as above 2800 ft2. What does the band name give a reader that the duty alone does not?', '["Which relation the duty came from, since the wetted area decides that and two duties either side of an edge sit on two different relations.", "The margin to the next edge, so a reader can see how far the area would have to move before the duty changed.", "The environment factor in force, since the credit is applied within a band rather than to the duty as a whole.", "The wetted height the area was formed on, which is what a reviewer needs in order to audit the area itself."]'::jsonb, 0, 'Without the band name, two duties either side of an edge look like two points on one curve.'),
  ('metering', 'advanced', 'final', null, 30, 'What is the practical difference between the tank capacity refusal and the loss control refusal on a missing efficiency?', '["One is raised by the engine and the other by the screen that calls it, which is why only the first carries a message of its own.", "One returns a null with a flag and the other a message with no flag.", "One fires on an input that is present and impossible, and the other on an input that is absent and cannot be assumed.", "One is counted in the register of fifteen items and the other is not, because only an absent input reaches the register."]'::jsonb, 2, 'A fill height below zero is impossible arithmetic, and an omitted control efficiency is unknown rather than zero.'),
  ('metering', 'advanced', 'final', null, 31, 'Which two routes does the fire result name for getting a vent capacity, and what do they share?', '["A rearrangement of the duty into scfh of air, or a vendor curve, and both start from the fire duty the engine returns.", "API 2000 against the heat input, or the vent manufacturer''s certified capacity curve, and neither is carried by this package.", "The band table in the standard, or a certified curve, and both start from the wetted area of 5881.0614 ft2.", "A calculated environment credit, or a certified curve, and both reduce the duty before a capacity is read against it."]'::jsonb, 1, 'The refusal costs one step rather than the whole calculation, because the duty the standard''s own relation needs is returned.'),
  ('metering', 'advanced', 'final', null, 32, 'What distinguishes a returned word from a returned number in the tank results of this tier?', '["A word is a display value and a number is a result, so the two come off different parts of the calculation.", "A word carries no tolerance, so a course can grade a word where it cannot grade a number to the same precision.", "A word is stable under a change of input and a number is not, which is why a word is the safer thing to quote in a report.", "A word cannot be interpolated, and it changes somewhere, which is what makes a boundary findable by asking the engine."]'::jsonb, 3, 'The shell returns a governing candidate, the venting returns a governing case and the fire calculation returns a heat input band.'),
  ('metering', 'advanced', 'final', null, 33, 'Both of the tank engine''s venting refusals come from one function. Which is it, and what are they?', '["thermalVenting, at a latitude factor above what the package will apply and with no capacity supplied.", "movementVenting, on a negative fill rate and on a draw rate above the crossover of 1083.0319 bbl/hr.", "thermalVenting, on a capacity above the stated proportional limit and on an insulation credit outside its range.", "fireVenting, on an environment factor above one and on a wetted height above the standard''s own cap."]'::jsonb, 0, 'movementVenting raises one refusal, on a negative fill rate, and fireVenting raises one, on an environment factor above one.'),
  ('metering', 'advanced', 'final', null, 34, 'A screening report quotes the fire duty of 25892440.2513 Btu/hr under a column headed emergency vent capacity. Which rule of this tier does that break?', '["Do not quote a figure at a precision above the class it belongs to.", "Do not quote a figure from one section beside a figure from another.", "Do not quote a figure the engine returns with a flag beside it.", "Do not present the duty as though it were a vent capacity, because a datasheet field is read as the quantity its heading names."]'::jsonb, 3, 'A duty is a heat input in Btu an hour and a vent is specified in scfh of air equivalent, and the relation between them is the one that is withheld.'),
  ('metering', 'advanced', 'final', null, 35, 'What is the argument for an engine returning its components rather than only its totals, as this module''s loss result does?', '["A total can be reached by very different routes, and a component that is undefined disappears inside a sum.", "A total cannot be checked against a golden case that carries components.", "A total is returned in one unit and the components in another, so a reader comparing them has to convert first.", "A total is what a tolerance is set around, so the components are what a course grades in its place."]'::jsonb, 0, 'On a product that boils at ambient the working half still produces a number, and a reader seeing only the sum would never know the standing half was undefined.'),
  ('metering', 'advanced', 'final', null, 36, 'A vent on this tank is being sized at the stated rates, and a colleague proposes the inward figure because inward failure is worse. What is wrong with the proposal?', '["Nothing is wrong, since the inward total of 23201.8178 scfh is conservative.", "The inward total is not a sizing quantity at all, because a vacuum vent is sized on the draw rate rather than on a total in scfh.", "The engine returns pressure as the governing case at these rates, and the governing case is what the sizing step reads.", "The two totals should be added, because a vent has to pass both directions and 25689.2574 scfh alone covers only one of them."]'::jsonb, 2, 'The judgement about which failure is worse belongs to the draw rate the facility can reach, and the crossover of 1083.0319 bbl/hr is where that judgement is made.'),
  ('metering', 'advanced', 'final', null, 37, 'Why does this course grade nothing that rests on the fifteen items in its register?', '["Because the register was written after the graded fields were chosen, so nothing in it could have reached them.", "Because every item in it belongs to the metering or the valve engine, and the tank engine carries everything the tank capstone needs.", "Because the items are all stated inputs, and a stated input cannot be graded when the caller is the one who supplied it.", "Because each is something the package says it does not carry, does not cite or will not answer, so an answer would rest on a value with no clause beside it."]'::jsonb, 3, 'Two of the fifteen are outright refusals, and a capstone field resting on either of those could not be answered at all.'),
  ('metering', 'advanced', 'final', null, 38, 'A vent supplier asks which figure on this tank their certified curve should be read against. What do you send them?', '["The fire duty, and you say that the conversion into a capacity is the step this package does not carry.", "The total outbreathing of 25689.2574 scfh, since a curve is published in scfh of air.", "The wetted area of 5881.0614 ft2, because a curve for an emergency vent is indexed on the area it is protecting.", "The nominal capacity of 19608.4845 bbl, because a vent is selected on tank size and the capacity is what the thermal side is keyed to."]'::jsonb, 0, 'Everything up to the refusal is returned, and the duty is the input the standard''s own relation needs.'),
  ('metering', 'advanced', 'final', null, 39, 'Two tanks report the same annual loss and opposite splits between the standing and working halves. What follows?', '["They are the same problem at two throughputs, because the split follows the throughput and the total is what a control device acts on.", "One of the two results is wrong, because the split on a fixed-roof tank is a property of the relations rather than of the tank.", "They are two different problems, because one family of equipment works on the vapour space and another on the displaced vapour.", "The difference is a reporting question rather than an engineering one."]'::jsonb, 2, 'On this tank the standing half is 3537.6108 lb/yr against a working half of 73605.2059 lb/yr, and the split is the first thing to read.'),
  ('metering', 'advanced', 'final', null, 40, 'The engine says its thermal rate per barrel and its latitude factor are its own stated choices. What does a reader do with that?', '["Replace them with values from the standard before quoting the result, since a stated factor cannot be used in a design calculation.", "Write down which factors were applied and where each came from, because the relation is the easy half and the factors are what a reviewer challenges.", "Treat the inbreathing figure as an extrapolation, in the way a tank above the stated capacity limit is treated.", "Ask for the figures to be recomputed at a latitude factor the package will accept, since 1.000000 is the value it refuses above."]'::jsonb, 1, 'The engine returns the rate at 1.000000 and the latitude factor at 1.000000 beside the answer so the basis travels with the figure.'),
  ('metering', 'advanced', 'final', null, 41, 'fireVenting raises one refusal of its own in this course. On what input?', '["An environment factor above one.", "A wetted area above the top band edge of 2800.0000 ft2, where the relation the duty comes from stops being carried.", "A request for the vent capacity, which is the withheld figure and is therefore the refusal this function is counted for.", "A liquid column above the standard''s own height cap, which the engine declines rather than silently limiting to 30.000000 ft."]'::jsonb, 0, 'The withheld vent capacity is a null with a flag rather than an error key, and the refusal counted against this function is the factor bound.'),
  ('metering', 'advanced', 'final', null, 42, 'Which of these figures would a learner be inventing rather than reading, on this tank?', '["The effective wetted height of 30.000000 ft, since the cap is a limit in the standard rather than a returned quantity.", "The crossover draw rate of 1083.0319 bbl/hr, since it is found by search rather than returned by any single call.", "The barrels per foot of shell at 544.6801, since it is formed from the cross section rather than returned in its own right.", "A required emergency vent capacity in scfh of air."]'::jsonb, 3, 'The vent column comes back null at every wetted area, and the engine exports its refusal as a named constant so a screen cannot print a blank.');
